export default function collect({page,previousState}){
 if(previousState===null)return {state:{items:[],offset:0},items:[],offset:0,more:true};
 if(!page||!Array.isArray(page.items)||!Number.isSafeInteger(page.offset)||page.offset!==previousState.offset||!Number.isSafeInteger(page.total)||page.total<0)throw Error('Invalid Spotify page');
 if(!Object.hasOwn(page,'next'))throw Error('Spotify page lacks next marker');
 const items=previousState.items.concat(page.items),next=page.next;
 if(next!==null&&next!==undefined&&(typeof next!=='string'||!next||page.items.length===0))throw Error('Invalid Spotify next page');
 const offset=page.offset+page.items.length;
 if(next!=null){const match=/[?&]offset=(\d+)(?:&|$)/.exec(next);if(!match||Number(match[1])!==offset)throw Error('Invalid Spotify next offset');}
 return {state:{items,offset},items,offset,more:next!=null};
}

