export default function select({playlists,name}){
 if(typeof name!=='string'||!name.trim()||name==='YOUR_PLAYLIST_NAME')throw Error('Set the playlist name');
 const matches=playlists.filter(x=>x?.name===name);if(matches.length!==1)throw Error('Expected exactly one playlist with this name');
 const id=matches[0].id;if(typeof id!=='string'||!id)throw Error('Playlist has no ID');return {id,name};
}

