export default function diff({saved,tracks,id,name}){
 const map=(entries,label)=>entries.map(x=>{if(typeof x?.track?.uri!=='string'||!x.track.uri||typeof x.added_at!=='string'||!Number.isFinite(Date.parse(x.added_at)))throw Error('Invalid '+label+' item');return {uri:x.track.uri,addedAt:x.added_at};}).sort((a,b)=>a.addedAt.localeCompare(b.addedAt));
 const liked=map(saved,'saved'),existing=map(tracks,'playlist');if(!liked.length)return {add:[],remove:[],id,name};
 const matched=new Set(),add=[];for(const x of liked){const index=existing.findIndex(y=>y.uri===x.uri);if(index<0)add.push({uri:x.uri});else matched.add(index)}const remove=existing.filter((_,i)=>!matched.has(i)).map(x=>({uri:x.uri}));return {add,remove,id,name};
}
